SELECT `keywords`.`WORD`, `keywords`.`RESERVED` FROM (SELECT `information_schema`.`keywords`.`WORD`, `information_schema`.`keywords`.`RESERVED` FROM `information_schema`.`keywords` EXCEPT SELECT `information_schema`.`keywords`.`WORD`, `information_schema`.`keywords`.`RESERVED` FROM `information_schema`.`keywords`) `keywords` ORDER BY `keywords`.`word` ASC;
SELECT `keywords`.`WORD`, `keywords`.`RESERVED` FROM (SELECT `information_schema`.`keywords`.`WORD`, `information_schema`.`keywords`.`RESERVED` FROM `information_schema`.`keywords` UNION SELECT `information_schema`.`keywords`.`WORD`, `information_schema`.`keywords`.`RESERVED` FROM `information_schema`.`keywords`) `keywords` ORDER BY `keywords`.`word` ASC;
SELECT `information_schema`.`keywords`.`WORD`, `information_schema`.`keywords`.`RESERVED` FROM `information_schema`.`keywords` WHERE `information_schema`.`keywords`.`RESERVED` = FALSE ORDER BY `information_schema`.`keywords`.`word` ASC;
SELECT `keywords`.`WORD`, `keywords`.`RESERVED`, `srfuzz_n1`.`e` FROM (SELECT `information_schema`.`keywords`.`WORD`, `information_schema`.`keywords`.`RESERVED` FROM `information_schema`.`keywords`) `keywords` , LATERAL generate_series(1,3,1) srfuzz_n1(`e`)  ORDER BY `keywords`.`word` ASC;